/* ------------------------------------------------------------------ */
/* Test                                                                */
/* ------------------------------------------------------------------ */

static void test_central(void)
{
	int err;

	err = bk_sync_init();
	if (err) {
		TEST_FAIL("Backchannel init failed (err %d)", err);
	}

	err = bt_enable(NULL);
	if (err != 0) {
		TEST_FAIL("Bluetooth init failed (err %d)", err);
	}

	err = bt_le_scan_start(BT_LE_SCAN_PASSIVE, device_found);
	if (err != 0) {
		TEST_FAIL("Scanning failed to start (err %d)", err);
	}

	printk("Scanning successfully started\n");

	WAIT_FOR_FLAG(flag_is_connected);

	/* Single ATT reads/writes are limited by the negotiated MTU. */
	const uint16_t att_mtu = bt_gatt_get_mtu(g_conn);

	/* Discover every generated characteristic by UUID. */
	uint16_t sensor_svc_temperature_handle = discover_chrc(SENSOR_SVC_TEMPERATURE_UUID);
	if (sensor_svc_temperature_handle == 0) {
		TEST_FAIL("sensor_svc/temperature not found");
	}
	printk("sensor_svc/temperature: value handle %u\n", sensor_svc_temperature_handle);
	uint16_t sensor_svc_humidity_handle = discover_chrc(SENSOR_SVC_HUMIDITY_UUID);
	if (sensor_svc_humidity_handle == 0) {
		TEST_FAIL("sensor_svc/humidity not found");
	}
	printk("sensor_svc/humidity: value handle %u\n", sensor_svc_humidity_handle);
	uint16_t sensor_svc_sampling_rate_handle = discover_chrc(SENSOR_SVC_SAMPLING_RATE_UUID);
	if (sensor_svc_sampling_rate_handle == 0) {
		TEST_FAIL("sensor_svc/sampling_rate not found");
	}
	printk("sensor_svc/sampling_rate: value handle %u\n", sensor_svc_sampling_rate_handle);
	uint16_t device_svc_device_name_handle = discover_chrc(DEVICE_SVC_DEVICE_NAME_UUID);
	if (device_svc_device_name_handle == 0) {
		TEST_FAIL("device_svc/device_name not found");
	}
	printk("device_svc/device_name: value handle %u\n", device_svc_device_name_handle);
	uint16_t device_svc_reboot_handle = discover_chrc(DEVICE_SVC_REBOOT_UUID);
	if (device_svc_reboot_handle == 0) {
		TEST_FAIL("device_svc/reboot not found");
	}
	printk("device_svc/reboot: value handle %u\n", device_svc_reboot_handle);
	uint16_t device_svc_event_flag_handle = discover_chrc(DEVICE_SVC_EVENT_FLAG_UUID);
	if (device_svc_event_flag_handle == 0) {
		TEST_FAIL("device_svc/event_flag not found");
	}
	printk("device_svc/event_flag: value handle %u\n", device_svc_event_flag_handle);

	/* Verify readable characteristics return the expected number of bytes.
	 * A single ATT read is capped at MTU-1, so larger values come back
	 * truncated at the first read.
	 */
	{
		uint16_t len = read_chrc(sensor_svc_temperature_handle);
		uint16_t expected = MIN(SENSOR_SVC_TEMPERATURE_SIZE, att_mtu - 1);

		if (len != expected) {
			TEST_FAIL("sensor_svc/temperature read len %u, expected %u", len, expected);
		}
	}
	{
		uint16_t len = read_chrc(sensor_svc_humidity_handle);
		uint16_t expected = MIN(SENSOR_SVC_HUMIDITY_SIZE, att_mtu - 1);

		if (len != expected) {
			TEST_FAIL("sensor_svc/humidity read len %u, expected %u", len, expected);
		}
	}
	{
		uint16_t len = read_chrc(sensor_svc_sampling_rate_handle);
		uint16_t expected = MIN(SENSOR_SVC_SAMPLING_RATE_SIZE, att_mtu - 1);

		if (len != expected) {
			TEST_FAIL("sensor_svc/sampling_rate read len %u, expected %u", len,
				  expected);
		}
	}
	{
		uint16_t len = read_chrc(device_svc_device_name_handle);
		uint16_t expected = MIN(DEVICE_SVC_DEVICE_NAME_SIZE, att_mtu - 1);

		if (len != expected) {
			TEST_FAIL("device_svc/device_name read len %u, expected %u", len, expected);
		}
	}

	/* Exercise writable characteristics; verify by read-back when possible. */
	{
		uint8_t pattern[SENSOR_SVC_SAMPLING_RATE_SIZE];
		/* An ATT write without long-write support is capped at MTU-3. */
		uint16_t wlen = MIN(sizeof(pattern), att_mtu - 3);

		for (size_t i = 0; i < sizeof(pattern); i++) {
			pattern[i] = (uint8_t)(0xa5 ^ i);
		}

		write_chrc(sensor_svc_sampling_rate_handle, pattern, wlen);
		{
			uint16_t len = read_chrc(sensor_svc_sampling_rate_handle);

			if (len < wlen || memcmp(read_buf, pattern, wlen) != 0) {
				TEST_FAIL("sensor_svc/sampling_rate read-back mismatch");
			}
		}
	}
	{
		uint8_t pattern[DEVICE_SVC_REBOOT_SIZE];
		/* An ATT write without long-write support is capped at MTU-3. */
		uint16_t wlen = MIN(sizeof(pattern), att_mtu - 3);

		for (size_t i = 0; i < sizeof(pattern); i++) {
			pattern[i] = (uint8_t)(0xa5 ^ i);
		}

		write_chrc(device_svc_reboot_handle, pattern, wlen);
	}

	/* Subscribe to every notification/indication source. */
	sensor_svc_temperature_sub.value_handle = sensor_svc_temperature_handle;
	err = bt_gatt_subscribe(g_conn, &sensor_svc_temperature_sub);
	if (err < 0) {
		TEST_FAIL("sensor_svc/temperature subscribe failed (err %d)", err);
	}
	WAIT_FOR_FLAG(sensor_svc_temperature_subscribed);
	sensor_svc_humidity_sub.value_handle = sensor_svc_humidity_handle;
	err = bt_gatt_subscribe(g_conn, &sensor_svc_humidity_sub);
	if (err < 0) {
		TEST_FAIL("sensor_svc/humidity subscribe failed (err %d)", err);
	}
	WAIT_FOR_FLAG(sensor_svc_humidity_subscribed);
	device_svc_event_flag_sub.value_handle = device_svc_event_flag_handle;
	err = bt_gatt_subscribe(g_conn, &device_svc_event_flag_sub);
	if (err < 0) {
		TEST_FAIL("device_svc/event_flag subscribe failed (err %d)", err);
	}
	WAIT_FOR_FLAG(device_svc_event_flag_subscribed);

	printk("All characteristics verified; signalling peripheral\n");

	/* Tell the peripheral to start pushing values. */
	bk_sync_send();

	/* Wait for the expected pushes. */
	for (int i = 0; i < WAIT_ITERS; i++) {
		if (sensor_svc_temperature_received >= NOTIFICATION_COUNT &&
		    sensor_svc_humidity_received >= 1 &&
		    device_svc_event_flag_received >= NOTIFICATION_COUNT) {
			break;
		}
		k_sleep(K_MSEC(10));
	}
	if (sensor_svc_temperature_received < NOTIFICATION_COUNT) {
		TEST_FAIL("sensor_svc/temperature: got %u values, expected %u",
			  sensor_svc_temperature_received, NOTIFICATION_COUNT);
	}
	if (sensor_svc_humidity_received < 1) {
		TEST_FAIL("sensor_svc/humidity: got %u values, expected %u",
			  sensor_svc_humidity_received, 1);
	}
	if (device_svc_event_flag_received < NOTIFICATION_COUNT) {
		TEST_FAIL("device_svc/event_flag: got %u values, expected %u",
			  device_svc_event_flag_received, NOTIFICATION_COUNT);
	}

	/* Verification complete; let the peripheral pass. */
	bk_sync_send();

	TEST_PASS("gatt_gen_multi central passed");
}

static const struct bst_test_instance test_central_def[] = {
	{
		.test_id = "central",
		.test_main_f = test_central,
	},
	BSTEST_END_MARKER,
};

struct bst_test_list *test_central_install(struct bst_test_list *tests)
{
	return bst_add_tests(tests, test_central_def);
}
